<script lang="ts">
  import { onMount } from 'svelte';
  import Icon from '#lib/Icon.svelte';
  import JobDetail from '#lib/JobDetail.svelte';
  import { api, message, statuses, titleCase } from '#lib/api';
  import type { Job } from '#lib/types';
  let jobs: Job[] = []; let loading=true; let error=''; let view='board'; let filter=''; let selected: Job | null=null;
  $: filtered = jobs.filter(j => (j.title+' '+j.company+' '+j.location).toLowerCase().includes(filter.toLowerCase()));
  async function load(){try{jobs=await api<Job[]>('/jobs');}catch(e){error=message(e);}finally{loading=false;}}
  onMount(() => {view=localStorage.getItem('career-ops-tracker-view') || 'board';load();});
  function setView(value:string){view=value;localStorage.setItem('career-ops-tracker-view',value);}
</script>
<svelte:head><title>Job tracker — Career Ops</title></svelte:head>
<div class="page-heading"><div><p class="eyebrow">ONE STEP AT A TIME</p><h1>Your job search, in view.</h1><p>Keep track of each role, from a first look to a final outcome.</p></div><a class="button-link primary" href="/"><Icon name="plus" size={15}/>Find roles</a></div>
<div class="pipeline-summary">{#each statuses as status}<div><span class="stage-dot {status}"></span><span>{titleCase(status)}</span><strong>{jobs.filter(j=>j.status===status).length}</strong></div>{/each}</div>
<div class="tracker-toolbar"><label class="filter"><Icon name="search" size={15}/><input aria-label="Filter tracked jobs" placeholder="Search your saved roles…" bind:value={filter}/></label><div class="tabs"><button class:selected={view==='board'} onclick={()=>setView('board')}><Icon name="board" size={13}/>Board</button><button class:selected={view==='list'} onclick={()=>setView('list')}><Icon name="list" size={13}/>List</button></div></div>
{#if error}<div class="error" role="alert">{error}</div>{/if}
{#if loading}<div class="loading-line"><span class="spinner"></span>Loading your pipeline…</div>{:else}<div class="tracker-layout" class:show-detail={selected}><div class="tracker-content">
  {#if view==='board'}<div class="board" role="region" aria-label="Application pipeline">{#each statuses as status}<section class="stage" aria-label={titleCase(status)+' applications'}><div class="stage-heading"><span class="stage-dot {status}"></span><h2>{titleCase(status)}</h2><span class="stage-count">{filtered.filter(j=>j.status===status).length}</span></div><div class="stage-cards">{#each filtered.filter(j=>j.status===status) as job}<button class="tracker-card" class:chosen={selected?.id===job.id} onclick={()=>selected=job}><span class="company-label">{job.company}</span><h3>{job.title}</h3><div class="meta"><Icon name="pin" size={11}/>{job.location}</div><div class="row between" style="margin-top:15px"><span class="badge">{job.fit_score ?? '—'} fit</span>{#if job.application?.outcome}<span class="outcome">{titleCase(job.application.outcome)}</span>{:else}<Icon name="arrow" size={12}/>{/if}</div></button>{:else}<div class="empty-stage"><Icon name={status==='found'?'search':status==='tailored'?'file':status==='applied'?'check':status==='interviewing'?'briefcase':'board'} size={19}/><p>{status==='found'?'New matches appear here':status==='tailored'?'Drafts ready for review':status==='applied'?'Applications you submit':status==='interviewing'?'Your conversations':'Final outcomes'}</p></div>{/each}</div></section>{/each}</div>
  {:else}<div class="panel list-panel"><table><thead><tr><th>Role & company</th><th>Location</th><th>Fit</th><th>Stage</th><th>Outcome</th></tr></thead><tbody>{#each filtered as job}<tr><td><button class="role-link" onclick={()=>selected=job}><strong>{job.title}</strong><small>{job.company}</small></button></td><td>{job.location}</td><td>{job.fit_score ?? '—'}</td><td><span class="badge">{titleCase(job.status)}</span></td><td>{job.application?.outcome ? titleCase(job.application.outcome) : '—'}</td></tr>{/each}</tbody></table>{#if !filtered.length}<div class="empty-state"><h3>{filter?'No matching saved roles':'Your tracker is ready'}</h3><p>Search for technology roles to add your first real jobs.</p><a class="button-link" href="/">Start a search</a></div>{/if}</div>{/if}
  <p class="fine-print tracker-footnote"><Icon name="info" size={12}/>Open a card to prepare materials or update its stage. “Applied” always requires your explicit action.</p>
</div>{#if selected}<JobDetail job={selected} onclose={()=>selected=null} onupdated={load}/>{/if}</div>{/if}
<style>
  .pipeline-summary{display:grid;grid-template-columns:repeat(5,1fr);background:white;border:1px solid var(--line);border-radius:11px;margin-bottom:24px}.pipeline-summary>div{padding:17px 15px;display:flex;align-items:center;gap:7px;border-right:1px solid var(--line);font-size:11px;color:#91a0b4}.pipeline-summary>div:last-child{border:0}.pipeline-summary strong{font-family:Manrope,sans-serif;font-size:19px;color:#526782;margin-left:auto}.stage-dot{height:6px;width:6px;border-radius:50%;background:#a4b5d0;flex-shrink:0}.stage-dot.tailored{background:#af9fdb}.stage-dot.applied{background:#78a8ec}.stage-dot.interviewing{background:#68bfa2}.stage-dot.resolved{background:#9eb4a7}.tracker-toolbar{display:flex;justify-content:space-between;gap:20px;margin-bottom:22px}.filter{display:flex;align-items:center;gap:9px;background:white;border:1px solid var(--line);padding:8px 12px;border-radius:7px;max-width:340px;flex:1;color:#a1afc4}.filter input{border:0;outline:none;width:100%;font-size:11px;color:var(--ink)}.filter input::placeholder{color:#a4afc0}.tracker-layout{display:grid;gap:22px;grid-template-columns:1fr}.tracker-layout.show-detail{grid-template-columns:minmax(0,1.2fr) minmax(310px,.8fr)}.tracker-content{min-width:0}.board{display:grid;grid-template-columns:repeat(5,minmax(165px,1fr));gap:13px;overflow:auto;padding-bottom:12px}.stage{background:#eff2f7;border:1px solid #e7ebf2;border-radius:10px;min-height:360px;padding:13px 10px}.stage-heading{display:flex;gap:6px;align-items:center;padding:3px 3px 17px}.stage-heading h2{font-size:11px;font-family:'DM Sans',sans-serif;font-weight:600;color:#6f819b;letter-spacing:0}.stage-count{margin-left:auto;color:#95a4b8;background:#e6ebf3;border-radius:4px;font-size:9px;padding:2px 5px}.stage-cards{display:grid;gap:11px}.tracker-card{text-align:left;display:block;min-width:0;padding:14px 12px;border-radius:8px;border:1px solid #e4e9f2;box-shadow:0 2px 4px #25385705;color:#8498b7;font-weight:400}.tracker-card.chosen{border-color:#99b7eb}.tracker-card h3{font-size:12px;line-height:1.6;margin:9px 0}.company-label{font-size:10px;color:#97a4b8}.tracker-card .meta{font-size:9px;gap:4px;line-height:1.6}.tracker-card .badge{font-size:9px}.outcome{font-size:9px;color:#8ba28f}.empty-stage{border:1px dashed #dce3ef;border-radius:7px;min-height:125px;padding:25px 10px;text-align:center;color:#b2bfd2}.empty-stage :global(svg){display:block;margin:auto auto 13px}.empty-stage p{font-size:10px;color:#a1afc3}.tracker-footnote{display:flex;align-items:center;gap:6px;margin-top:17px}.list-panel{overflow:auto;padding:0}table{width:100%;border-collapse:collapse;font-size:11px;text-align:left;min-width:590px}th{background:#fafbfd;padding:13px 18px;font-size:10px;font-weight:500;color:#9ba7b9}td{border-top:1px solid var(--line);padding:15px 18px;color:#8a98ad}.role-link{padding:0;border:0;display:block;text-align:left;background:transparent!important;max-width:280px}.role-link strong{font-size:11px;line-height:1.6}.role-link small{display:block;font-size:10px;font-weight:400;color:#9ba6b8;margin-top:4px}@media(max-width:1000px){.tracker-layout.show-detail{grid-template-columns:1fr}.pipeline-summary>div{padding:14px 10px;gap:4px;font-size:10px}.pipeline-summary strong{font-size:16px}}@media(max-width:700px){.pipeline-summary{grid-template-columns:repeat(5,1fr)}.pipeline-summary>div{padding:12px 4px;flex-direction:column;gap:7px;font-size:9px}.pipeline-summary .stage-dot{display:none}.pipeline-summary strong{margin:0}.tracker-toolbar{gap:10px}.filter{padding:9px;font-size:10px}.tracker-toolbar .tabs button{padding:6px 8px}.board{grid-template-columns:repeat(5,180px)}.tracker-footnote{align-items:flex-start}}
</style>
